<div class="section-title"><div><h1>Manage reports</h1><p class="muted">Review and update report status.</p></div></div><div class="card" style="margin-bottom:20px"><a href="?">All</a> · <a href="?type=lost">Lost</a> · <a href="?type=found">Found</a></div>
<div class="table-wrap"><table><thead><tr><th>ID</th><th>Report</th><th>Reporter</th><th>Date/location</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><?= (int)$item['id']?></td><td><a href="<?= h(url('item.php?id='.$item['id']))?>"><?= h($item['title'])?></a><br><span class="muted"><?= h(ucfirst($item['report_type']))?> · <?= h($item['category'])?></span></td><td><?= h($item['reporter_name'])?></td><td><?= h($item['incident_date'])?><br><?= h($item['location'])?></td><td><?= status_badge($item['status'])?></td><td><form class="inline-form" method="post"><?= csrf_field()?><input type="hidden" name="item_id" value="<?= (int)$item['id']?>"><select name="status"><?php foreach(['open','claimed','returned','closed'] as $s):?><option value="<?= $s?>" <?= $item['status']===$s?'selected':''?>><?= ucfirst($s)?></option><?php endforeach;?></select><button class="btn btn-small">Save</button></form></td></tr><?php endforeach;?></tbody></table></div>
